        public override string ToString()
        {
            var sb = new StringBuilder(100);
            var m = new ListStatus();
            m.WrapForDecode(_buffer, _offset, _actingBlockLength, _actingVersion);
            m.BuildString(sb);
            return sb.ToString();
        }

        internal void BuildString(StringBuilder builder)
        {
            if (_buffer == null)
            {
                throw new ArgumentNullException("_buffer");
            }

            int originalLimit = this.Limit;
            this.Limit = _offset + _actingBlockLength;
            builder.Append("[ListStatus](sbeTemplateId=");
            builder.Append(ListStatus.TemplateId);
            builder.Append("|sbeSchemaId=");
            builder.Append(ListStatus.SchemaId);
            builder.Append("|sbeSchemaVersion=");
            if (_parentMessage._actingVersion != ListStatus.SchemaVersion)
            {
                builder.Append(_parentMessage._actingVersion);
                builder.Append('/');
            }
            builder.Append(ListStatus.SchemaVersion);
            builder.Append("|sbeBlockLength=");
            if (_actingBlockLength != ListStatus.BlockLength)
            {
                builder.Append(_actingBlockLength);
                builder.Append('/');
            }
            builder.Append(ListStatus.BlockLength);
            builder.Append("):");

            builder.Append("ListID=");
            builder.Append(this.ListID);
            builder.Append('|');
            builder.Append("ContingencyType=");
            builder.Append(this.ContingencyType);
            builder.Append('|');
            builder.Append("ListStatusType=");
            builder.Append(this.ListStatusType);
            builder.Append('|');
            builder.Append("ListOrderStatus=");
            builder.Append(this.ListOrderStatus);
            builder.Append('|');
            builder.Append("ListRejectReason=");
            builder.Append(this.ListRejectReason);
            builder.Append('|');
            builder.Append("TransactTime=");
            builder.Append(this.TransactTime);
            builder.Append('|');
            builder.Append("Orders=[");
            var orders = this.Orders;
            if (orders.Count > 0)
            {
                var first = true;
                while (orders.HasNext)
                {
                    if (!first)
                    {
                        builder.Append(',');
                    }
                    first = false;
                    orders.Next().BuildString(builder);
                }
            }
            builder.Append("]");
            builder.Append('|');
            builder.Append("ClListID=");
            builder.Append('\'').Append(GetClListID()).Append('\'');
            builder.Append('|');
            builder.Append("OrigClListID=");
            builder.Append('\'').Append(GetOrigClListID()).Append('\'');

            this.Limit = originalLimit;

        }
